                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.legacyCode()).isEqualTo("TECLA NO VALIDA");
                    assertThat(be.code()).isEqualTo("INVALID_KEY");
                    assertThat(be.getMessage()).isEqualTo("TECLA NO VALIDA");
                });
    }

